function moveIsClear(id,from,to,pos,e){const bound=e.bounds??SIZES[e.size],[a,b]=motionBoxes(id,from,to);if([...a,...b].some(q=>q.min[0]<-1e-6||q.max[0]>bound.w+1e-6||q.min[2]<-1e-6||q.max[2]>bound.d+1e-6))return false;for(const p of[from,to])for(const q of boxes(id,p))if(q.min[0]<-1e-6||q.max[0]>bound.w+1e-6||q.min[2]<-1e-6||q.max[2]>bound.d+1e-6)return false;for(let k=0;k<a.length;k++){for(const f of FIXED)if(movingCollision(a[k],b[k],f,f,CLEARANCE))return false;for(const other of BODIES)if(other.id!==id)for(const ob of boxes(other.id,pos[other.id]))if(movingCollision(a[k],b[k],ob,ob,CLEARANCE))return false;}return true;}
function horizontalPath(id,start,end,pos,e){if(equal(start,end))return[];const bound=e.bounds??SIZES[e.size],f=footprint(BY_ID[id]),xs=new Set([start.x,end.x,0,bound.w-f.w]),zs=new Set([start.z,end.z,0,bound.d-f.d]);for(const other of BODIES){if(other.id===id)continue;for(const q of boxes(other.id,pos[other.id]))if(q.max[1]+CLEARANCE>start.y&&q.min[1]-CLEARANCE<start.y+HEIGHT){xs.add(q.min[0]-f.w-.4);xs.add(q.max[0]+.4);zs.add(q.min[2]-f.d-.4);zs.add(q.max[2]+.4);}}const norm=s=>[...new Set([...s].map(v=>Math.round(v*1e6)/1e6))],xx=norm(xs).filter(x=>x>=-1e-6&&x+f.w<=bound.w+1e-6).sort((a,b)=>a-b),zz=norm(zs).filter(z=>z>=-1e-6&&z+f.d<=bound.d+1e-6).sort((a,b)=>a-b),key=(x,z)=>`${x.toFixed(5)},${z.toFixed(5)}`,nodes=new Map();for(const x of xx)for(const z of zz){const p={...start,x,y:start.y,z};if(moveIsClear(id,p,p,pos,e))nodes.set(key(x,z),p);}const src=key(start.x,start.z),dst=key(end.x,end.z);if(!nodes.has(src)||!nodes.has(dst))throw Error(`${id}: デッキの開始・到着占有が成立しません`);const dist=new Map([[src,0]]),prev=new Map(),open=new Set([src]);while(open.size){const k=[...open].sort((a,b)=>dist.get(a)-dist.get(b))[0];open.delete(k);if(k===dst)break;const p=nodes.get(k),xi=xx.indexOf(p.x),zi=zz.indexOf(p.z);for(const[nx,nz]of[[xi-1,zi],[xi+1,zi],[xi,zi-1],[xi,zi+1]]){if(nx<0||nx>=xx.length||nz<0||nz>=zz.length)continue;const nk=key(xx[nx],zz[nz]),q=nodes.get(nk);if(!q||!moveIsClear(id,p,q,pos,e))continue;const nd=dist.get(k)+Math.abs(q.x-p.x)+Math.abs(q.z-p.z);if(nd<(dist.get(nk)??Infinity)-1e-7){dist.set(nk,nd);prev.set(nk,k);open.add(nk);}}}if(!dist.has(dst))throw Error(`${id}: 保管体・一時退避体を避ける水平経路なし`);const route=[];for(let k=dst;k!==src;k=prev.get(k))route.unshift(nodes.get(k));return route;}
function coreRecipes(from,to,e){const target=placements(to,e),upper=LEVELS[1],life=(x,z,y=upper)=>({x:x*8.4,z:z*8.4,y});if(from==='A'&&to==='B')return[['R2',target.R2,'同階の空きドックへ'],['C0',target.C0,'予備廊下を挿入'],['H1',target.H1,'広間を西側へ'],['L1',target.L1,'集会室を第三層へ']];if(from==='B'&&to==='C'){const large=e.size==='same'?[['L1',life(2,1,0),'空欄へ仮着床'],['H1',target.H1,'広間を東側へ'],['L1',target.L1,'同階で新しい平面位置へ']]:[['H1',{x:25.6,y:DECK,z:17.2},'東南の一時退避ベイ'],['L1',target.L1,'集会室を西へ再配置'],['H1',target.H1,'一時退避から第三層へ']];return[...large,['J3',target.J3,'交差廊下を奥の列へ'],['C0',target.C0,'予備廊下を保管'],['R2',target.R2,'住戸を前の列へ'],['J1',life(1,2),'複数空欄・仮着床'],['R3',target.R3,'同階で南北通路を移動'],['J1',target.J1,'行止りドックへ']];}if(from==='C'&&to==='A')return[['L1',target.L1,'集会室を東へ'],['J3',target.J3,'交差廊下を前の列へ'],['J1',life(1,2),'空欄を再利用'],['R3',target.R3,'個室201を奥へ'],['J1',target.J1,'南北廊下を再接続']];throw Error('Supported sequence is A→B→C→A');}
function recipes(from,to,e){const target=placements(to,e),buffer={x:50.4,y:DECK,z:8.4},swap=(a,b)=>[[a,buffer,'東翼の空きベイへ一時退避'],[b,target[b],'東翼の居室を別の生活階へ'],[a,target[a],'東翼の居室を再着床']];return [...coreRecipes(from,to,e),...(from==='A'?swap('E1','E3'):from==='B'?[...swap('E3','E1'),...swap('E2','E4')]:swap('E4','E2'))];}
const stage4Recipes=recipes;
