function serialJobs(from,to,e){const pos=structuredClone(placements(from,e)),jobs=[];for(const[id,end,tag]of [...splitRecipes(from,to,e),...['N4','S1'].map(id=>[id,placements(to,e)[id],id==='N4'?'回転ベイ経由・泉の向きを変更':'遠隔区域への実搬送・帰還'])]){if(equal(pos[id],end))continue;const fromPose={...pos[id]},stages=[];const add=(p,label)=>{const a={...pos[id]};if(equal(a,p))return;if(!moveIsClear(id,a,p,pos,e))throw Error(`${id}: ${label} の掃引または離隔が不成立`);const axis=['x','y','z','angle'].filter(k=>Math.abs((a[k]??0)-(p[k]??0))>1e-7);if(axis.length!==1)throw Error('non-axis leg');const distance=Math.abs((a[axis[0]]??0)-(p[axis[0]]??0));stages.push({label:`${id}・${label}`,duration:Math.max(.1,distance/(axis[0]==='angle'?30:axis[0]==='y'?3:4)),motions:[{id,from:a,to:{...p}}]});pos[id]={...p};};const deck=id==='M1'?LOWER_DECK:DECK;add({...pos[id],y:deck},'昇降・デッキへ');if(id==='N4'&&(pos[id].angle??0)!==(end.angle??0)){for(const p of horizontalPath(id,pos[id],{...ROTATION_BAY,angle:pos[id].angle},pos,e))add(p,'回転用の退避空間へ');add({...pos[id],angle:end.angle},'90度回転・全円包絡検査');}for(const p of horizontalPath(id,pos[id],{...end,y:deck},pos,e))add(p,tag);add(end,tag);jobs.push({id,from:fromPose,to:{...end},tag,stages,duration:stages.reduce((n,s)=>n+s.duration,0)});}return jobs;}
