const cache=new Map();
export function planTransfer(from,to,options=DEFAULT_EXPERIMENT){const e={...DEFAULT_EXPERIMENT,...options},key=JSON.stringify([from,to,e]);if(cache.has(key))return structuredClone(cache.get(key));const base={from,to,experiment:e,initial:placements(from,e),target:placements(to,e)};let result;try{const jobs=serialJobs(from,to,e);let data;if(e.method==='cooperative')data=coordinate(jobs,base);else{let time=0;data={stages:jobs.flatMap(j=>j.stages),reservations:jobs.map(j=>{const x={id:j.id,start:time,end:time+j.duration,tag:j.tag,from:j.from,to:j.to};time=x.end;return x;})};}result={...base,...data,duration:data.stages.reduce((n,s)=>n+s.duration,0),planningError:null};const check=validatePlan(result);if(!check.ok)result.planningError=`最終連続検査: ${check.errors[0].type}`;}catch(error){result={...base,stages:[],reservations:[],duration:0,planningError:error.message};}cache.set(key,result);return structuredClone(result);}
export function validatePlan(plan,initial=plan.initial??placements(plan.from,plan.experiment),clearance=CLEARANCE){const pos=structuredClone(initial),errors=[];let checks=0,maxConcurrent=0;const bound=plan.experiment?.bounds??SIZES[plan.experiment?.size??DEFAULT_EXPERIMENT.size];if(plan.planningError)errors.push({type:'planning-failed',reason:plan.planningError});for(const[id,p]of Object.entries(initial))for(const q of boxes(id,p))if(q.min[0]<-1e-6||q.max[0]>bound.w+1e-6||q.min[2]<-1e-6||q.max[2]>bound.d+1e-6)errors.push({id,type:'initial-outside-range'});
 for(let i=0;i<BODIES.length;i++){const id=BODIES[i].id;for(const a of boxes(id,initial[id])){for(const f of FIXED){checks++;if(movingCollision(a,a,f,f,clearance))errors.push({id,other:f.id,type:'initial-fixed-clearance'});}for(let j=i+1;j<BODIES.length;j++)for(const b of boxes(BODIES[j].id,initial[BODIES[j].id])){checks++;if(movingCollision(a,a,b,b,clearance))errors.push({id,other:BODIES[j].id,type:'initial-body-clearance'});}}}
 for(let si=0;si<plan.stages.length;si++){const s=plan.stages[si],moving=new Map(s.motions.map(m=>[m.id,m]));maxConcurrent=Math.max(maxConcurrent,moving.size);if(moving.size!==s.motions.length)errors.push({stage:si,type:'duplicate-mover'});for(const m of s.motions){if(Math.abs((m.from.angle??0)-(m.to.angle??0))>1e-8){if(BY_ID[m.id].cells.length!==1)errors.push({stage:si,id:m.id,type:'unsupported-rotation'});for(const q of motionBoxes(m.id,m.from,m.to).flat())if(q.min[0]<-1e-6||q.max[0]>bound.w+1e-6||q.min[2]<-1e-6||q.max[2]>bound.d+1e-6)errors.push({stage:si,id:m.id,type:'rotation-envelope-outside'});}if(!equal(pos[m.id],m.from))errors.push({stage:si,id:m.id,type:'discontinuous-start'});if(['x','y','z','angle'].filter(k=>Math.abs((m.from[k]??0)-(m.to[k]??0))>1e-7).length!==1)errors.push({stage:si,id:m.id,type:'non-axis-route'});for(const p of[m.from,m.to])for(const q of boxes(m.id,p))if(q.min[0]<-1e-6||q.max[0]>bound.w+1e-6||q.min[2]<-1e-6||q.max[2]>bound.d+1e-6)errors.push({stage:si,id:m.id,type:'outside-range'});}
  for(let i=0;i<BODIES.length;i++){const id=BODIES[i].id,m=moving.get(id),[a0,a1]=motionBoxes(id,pos[id],m?.to??pos[id]);if(m)for(let k=0;k<a0.length;k++)for(const f of FIXED){checks++;if(movingCollision(a0[k],a1[k],f,f,clearance))errors.push({stage:si,id,other:f.id,type:'fixed-clearance'});}for(let j=i+1;j<BODIES.length;j++){const jd=BODIES[j].id,n=moving.get(jd);if(!m&&!n)continue;const [b0,b1]=motionBoxes(jd,pos[jd],n?.to??pos[jd]);for(let a=0;a<a0.length;a++)for(let b=0;b<b0.length;b++){checks++;if(movingCollision(a0[a],a1[a],b0[b],b1[b],clearance))errors.push({stage:si,id,other:jd,type:'body-clearance'});}}}for(const m of s.motions)pos[m.id]={...m.to};}
 for(const id of Object.keys(plan.target))if(!equal(pos[id],plan.target[id]))errors.push({id,type:'wrong-destination'});return{ok:!errors.length,stages:plan.stages.length,checks,maxConcurrent,duration:plan.duration,clearance,area:bound.w*bound.d,areaRatio:bound.w*bound.d/(LIFE_BOUNDS.w*LIFE_BOUNDS.d),height:Math.max(...LEVELS)+HEIGHT-Math.min(...LEVELS),decks:2,emptyDockTransfers:plan.reservations?.filter(r=>r.tag.includes('空欄')||r.tag.includes('仮着床')).length??0,errors};}
export function positionDuring(plan,time){const pos=structuredClone(plan.initial);let elapsed=0;for(const s of plan.stages){if(time>=elapsed+s.duration-1e-8){for(const m of s.motions)pos[m.id]={...m.to};}else{const t=Math.max(0,(time-elapsed)/s.duration);for(const m of s.motions)pos[m.id]=mix(m.from,m.to,t);break;}elapsed+=s.duration;}return pos;}
export function comparison(){return Object.keys(SIZES).flatMap(size=>['serial','cooperative'].map(method=>({size,method,transitions:['A','B','C'].map(from=>({from,to:NEXT[from],...validatePlan(planTransfer(from,NEXT[from],{size,method}))}))})));}
